$('toggleCondenser').onclick=()=>{if(!['playing','paused','lab'].includes(run.state)||run.lab.gun.type!=='flame')return;run.condenser.toggle();syncCondenser()};
$('materialCards').addEventListener('click',e=>{const b=e.target.closest('[data-add]');if(b)move(b.dataset.add,'furnace')});$('furnaceContents').addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(b)move(b.dataset.remove,'inventory')});$('recipeCards').addEventListener('click',e=>{const b=e.target.closest('[data-recipe]');if(b&&run.state==='lab'&&!dialogType){setLabPane('craft');selected=b.dataset.recipe;syncLab()}});
$('returnAll').onclick=()=>{if(run.state==='lab'&&!dialogType){run.lab.returnAll();syncLab()}};$('craft').onclick=requestCraft;$('nextWave').onclick=()=>{if(dialogType)return;if(run.nextWave()){setSidebarTab('equipment');clearInput();sync();toast(`${gunName()} Lv.${run.lab.gun.level} · 新一关开始 · 当前生命 ${Math.ceil(run.hp)}`);$('arena').focus({preventScroll:true})}};$('ignition').onchange=()=>{if(run.state==='lab'&&!dialogType){run.lab.ignition=$('ignition').checked;syncLab()}};$('pause').onclick=pause;$('openLog').onclick=openLog;$('sound').onclick=()=>{gameAudio.setEnabled(!gameAudio.enabled);syncSound();gameAudio.play('click')};
function dragStart(e,selector,from){const b=e.target.closest(selector);if(!b||run.state!=='lab'||dialogType){e.preventDefault();return}const id=b.dataset.add||b.dataset.remove;e.dataTransfer.setData('application/x-valence',JSON.stringify({id,from}));e.dataTransfer.effectAllowed='move'}
$('materialCards').addEventListener('dragstart',e=>dragStart(e,'[data-add]','inventory'));$('furnaceContents').addEventListener('dragstart',e=>dragStart(e,'[data-remove]','furnace'));
for(const [id,to,expected]of [['furnace','furnace','inventory'],['backpack','inventory','furnace']]){const area=$(id);area.addEventListener('dragover',e=>{if(run.state==='lab'&&!dialogType){e.preventDefault();area.classList.add('drag-over')}});area.addEventListener('dragleave',()=>area.classList.remove('drag-over'));area.addEventListener('drop',e=>{e.preventDefault();area.classList.remove('drag-over');try{const data=JSON.parse(e.dataTransfer.getData('application/x-valence'));if(data.from===expected)move(data.id,to)}catch{}})}
$('dialogOverlay').addEventListener('click',e=>{if(e.target===$('dialogOverlay'))closeDialog()});
function moveJoy(e){const r=$('joystick').getBoundingClientRect(),dx=e.clientX-r.left-r.width/2,dy=e.clientY-r.top-r.height/2,n=Math.hypot(dx,dy),s=n>30?30/n:1;joy={x:dx*s/30,y:dy*s/30};$('stick').style.transform=`translate(${dx*s}px,${dy*s}px)`}
$('joystick').addEventListener('pointerdown',e=>{if(run.state!=='playing'||pointer!==null)return;e.preventDefault();pointer=e.pointerId;$('joystick').setPointerCapture(pointer);moveJoy(e)});$('joystick').addEventListener('pointermove',e=>{if(e.pointerId===pointer)moveJoy(e)});for(const n of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(n,e=>{if(e.pointerId===pointer)clearInput()});
window.addEventListener('keydown',e=>{const key=e.key.toLowerCase();if(dialogType){if(key==='escape'){e.preventDefault();closeDialog()}if(key==='tab'){const items=[...$('dialogCard').querySelectorAll('button')];if(items.length){let at=items.indexOf(document.activeElement),next=(at+(e.shiftKey?-1:1)+items.length)%items.length;e.preventDefault();items[next].focus()}}return}if(['arrowup','arrowdown','arrowleft','arrowright'].includes(key)&&run.state==='playing')e.preventDefault();if(e.repeat)return;if(run.state==='lab'&&['arrowleft','arrowright'].includes(key)&&!['SELECT','INPUT','TEXTAREA'].includes(e.target?.tagName)){e.preventDefault();browseRecipe(key==='arrowleft'?-1:1);return}if(run.state==='reward'&&['1','2','3'].includes(key)){e.preventDefault();selectReward(run.rewardChoices[Number(key)-1]);return}if(run.state==='upgrade'&&['1','2','3'].includes(key)){e.preventDefault();chooseAbility(run.upgradeChoices[Number(key)-1]);return}if(key==='enter'&&run.state==='menu'){e.preventDefault();start();return}if(key==='escape'){pause();return}keys[key]=true});window.addEventListener('keyup',e=>{keys[e.key.toLowerCase()]=false});
function autoPause(){clearInput();if(run.state==='playing'){run.state='paused';sync()}}window.addEventListener('blur',autoPause);document.addEventListener('visibilitychange',()=>{last=performance.now();if(document.hidden)autoPause()});
function frame(now){const dt=Math.min(.05,Math.max(0,(now-last)/1000||0));last=now;run.step(dt,{viewport:$('arena').getBoundingClientRect(),x:(keys.d||keys.arrowright?1:0)-(keys.a||keys.arrowleft?1:0)+joy.x,y:(keys.s||keys.arrowdown?1:0)-(keys.w||keys.arrowup?1:0)+joy.y});gameAudio.update(run);for(const event of run.events){if(event==='lootQueued')toast(run.lastQueued||'战利品已收纳 · 关间选择');if(event==='gunPickup')toast(run.lastPickup||'化学枪已装配');if(event==='condenserBurst')toast('水包蓄满 · 自动向侧后方喷水！');if(event==='elite')toast('精英'+ENEMY_TYPES[WAVE_NEW_TYPES[run.wave-1]].name+' · 高速 / 高伤 / 高频攻击');if(event==='finalTransform')toast('形态转换 · '+FORM_NAMES[(run.enemies.find(e=>e.type===6)?.phase||1)-1]);if(event==='boss')toast(run.wave===10?'熵灭实验体 · 最终战！':'失控反应釜出现 · 注意预警与绿色缺口');if(event==='bossRing')toast('高压冲击：移向绿色缺口，避开冲击弧');if(event==='bossZone')toast('地面已锁定：离开橙色警戒区');if(event==='overdrive')toast('反应釜过载！出招更快，注意连续冲击');if(event==='hurt'){renderer.shake=10;}}run.events=[];if(run.state!=='lab')renderer.draw(run,now/1000);sync();if(now>toastUntil)$('toast').classList.add('hidden');requestAnimationFrame(frame)}
